import type { FnContext } from './context';
import type { Part } from './parts';
import type { Opt, ReportKind, WatchKind } from './rows';

export type EntryKind = "you" | "agent" | "from_agent" | "tools" | "card" | "page" | "report" | "stopped" | "to_agent" | "thinking" | "compacting" | "compacted" | "notice" | "not_delivered" | "landed" | "pr" | "artifact" | "answered" | "approval" | "scheduled" | "turn_failed" | "wake" | "unknown";

/**
 * What a tool call did, for the counted summary.
 */
export type ToolKind = "read" | "edit" | "run" | "search" | "other";

/**
 * Where a tool call is: running, done, failed (R11, amb-win S9).
 */
export type ToolState = "run" | "ok" | "err" | "unknown";

/**
 * What the approvals gate holds a running call for (the hub's `sb gate :
 * check|card <n>` lines, approvals-design.md §3.1): the checker judges
 * it (`checking…` after 250 ms), or a card waits on him (`? waiting for
 * you`).
 */
export type GateWait = "check" | "card" | "unknown";

/**
 * A running call held by the gate, since `at_ms` (its gate line's time).
 */
export type ToolGate = { wait: GateWait, at_ms: number, };

/**
 * A file an edit touched, with its lines added and removed (the TUI's
 * `± file +18 −6`; a move reads `old → new`).
 */
export type FileCount = { path: string, add: number, del: number, };

/**
 * A view's state (docs/mcp-apps.md C4): `live` while its views file
 * (the call's full result) exists; `expired` once the daily prune took
 * it (the hub marks it, [`expire_views`]).
 */
export type ViewState = "live" | "expired" | "unknown";

/**
 * A view of a tool call (an MCP App, docs/mcp-apps.md C3-C4): its
 * plugin, its server (`~views`: a plugin's static view), its `ui://`
 * resource and the call id that names its full result
 * (`<agent dir>/views/<call>.json`).
 */
export type ToolView = { plugin: string, server: string, uri: string, call: string, state: ViewState, };

export type ToolItem = { pos: number, 
/**
 * the call's number in its transcript (`tool #N`, the runtime's
 * per-process count: not unique in a thread, `pos` is)
 */
id: number, at_ms: number, 
/**
 * the tool's name (`bash`); "" until the call's `tool` line
 */
name?: string, 
/**
 * its args as the call line gives them, unescaped, [`cap`]ped
 */
args?: string, 
/**
 * the model's one line for it (`tool_intent`, bash and TypeScript
 * calls: "running the tests")
 */
intent?: string | null, 
/**
 * the account a connector call runs as (`tool_account`, its label:
 * his title for it, else its name), only when the connector has 2 or
 * more; the row shows it after its name
 */
account?: string | null, 
/**
 * its intent ("running the tests"), else `name: first line of args`
 */
text: string, kind: ToolKind, 
/**
 * a `sb land`
 */
land?: boolean, 
/**
 * running until its result line, then ok or err
 */
state: ToolState, 
/**
 * the approvals gate holds it (running only: the gate's `done` line
 * and the call's end clear it)
 */
gate?: ToolGate | null, 
/**
 * its duration: the result line's time minus the call line's
 * ([`words::tool_ms`]); none while it runs or on a replay
 */
ms?: number | null, 
/**
 * a failed bash call's exit code (`exit 1: …`)
 */
exit?: number | null, 
/**
 * a failed call's first error line, the TUI's row under it
 */
err?: string | null, 
/**
 * the full command or args (the runtime's tool_code), [`cap`]ped
 */
code?: string | null, 
/**
 * its output as the result line gives it, [`cap`]ped
 */
out?: string | null, 
/**
 * an edit's files with their line counts (the window formats
 * `+18 −6` from them: counts, like the folds)
 */
files?: Array<FileCount>, 
/**
 * its views (MCP Apps, the runtime's `tool_view` lines), in their
 * lines' order: a `run_typescript` that called two tools with a view
 * has two
 */
views?: Array<ToolView>, };

export type Tools = { count: number, 
/**
 * counted words: "read 6 files, ran 4 commands"
 */
summary: string, items: Array<ToolItem>, };

export type EntryCard = { id: number, question: string, options: Array<Opt>, answered: boolean, 
/**
 * its kind, the same word as the hub's card row (`rows::Card.kind`:
 * `question`, `blocked`, `done`, …, an open set; `rows::card_rank`
 * reads it); none from an older hub
 */
kind?: string | null, 
/**
 * who asked (`rows::Card.agent`, the line's `@name`)
 */
agent?: string | null, 
/**
 * how it was closed, the hub's word on its `card-closed` line
 * (`answered`, `answered via @docs`, `accepted`, `refused`, …, BISE-31):
 * the card fades with it; none while that line hasn't come
 */
closed?: string | null, };

export type PageRef = { id: string, title: string, v?: number | null, url: string, };

export type ReportRef = { kind: ReportKind, };

/**
 * A `thinking` entry: how long the model thought (ms, 0 unknown: a
 * replay) and what.
 */
export type Thinking = { ms: number, text: string, };

/**
 * Where his message is (contract C3, BISE-86): `sent` (·), `received`
 * by the agent (✓, steering), `read` by the model (✓✓: steered, or its
 * turn started), `failed`: the hub could not deliver it (✗). Only ever
 * moves up, in that order ([`lines::deliver`], the one rule).
 */
export type Delivery = "sent" | "received" | "read" | "failed" | "unknown";

/**
 * How a notice reads: info (dim), warn (▲, what to do), err (✗).
 */
export type NoticeLevel = "info" | "warn" | "err" | "unknown";

/**
 * A `notice` entry: its level and its words ([`words::notice`]).
 */
export type Notice = { level: NoticeLevel, text: string, 
/**
 * H9 (ambient-lead m_19827, architect m_19836): a model call that
 * failed and waits to retry, as data. A run of them in one turn is one
 * entry, updated at its pos ([`lines::is_same_retry_run`])
 */
retry?: Retry | null, };

/**
 * A `not_delivered` entry: the agent his message didn't reach, and his
 * text (BISE-86: send again or drop it).
 */
export type NotDelivered = { to: string, text: string, };

/**
 * A `landed` entry (site/m/artifacts D): `agent`'s commits from `from`
 * landed on `target` at `sha`; the diff's size.
 */
export type Landed = { agent: string, target: string, from: string, sha: string, files: number, add: number, del: number, };

/**
 * What a PR's news means for him (pr-design §4), never a color: `news`
 * (opened, reviewed, merged...), `done` (nothing for him to do),
 * `failing` (its checks fail). The TUI maps it to its look.
 */
export type PrNewsState = "news" | "done" | "failing" | "unknown";

/**
 * A `pr` entry: the PR's number, its link, the news's words.
 */
export type PrNews = { number: number, url: string, text: string, state: PrNewsState, };

/**
 * An `artifact` entry (site/m/artifacts C): what was made; `kind_word`
 * as the TUI's chip says it (`page`, `PR`, `file`), `url` when it is a
 * page the hub serves.
 */
export type Made = { id: string, agent: string, title: string, kind: string, kind_word: string, v: number, url?: string | null, };

/**
 * An image he attached: its label (`[Image #1]`, or its file name) and
 * his source path (the chip's thumbnail). Never the store's b64 path.
 */
export type ImageRef = { name: string, path: string, };

/**
 * An `answered` entry: main answered `agent`'s question for him.
 */
export type Answered = { agent: string, question: string, 
/**
 * his words only, never an image marker or the file list (R41)
 */
answer: string, why: string, 
/**
 * the images he pasted with it: the window shows each as its chip
 */
images?: Array<ImageRef>, 
/**
 * his other files (absolute paths)
 */
files?: Array<string>, };

/**
 * An `approval` entry: his answer, folded (`you allowed api: rm -rf
 * target`, `you answered perf: both`); `note` the words under it;
 * `card`: the item it answers, for an answer to an item (the hub's
 * `route` line, BISE-305/307), so a client that folded the answer
 * itself knows it is the same one; `to`: the agent that answer went to
 * (the route line's asker), so a click on the row opens that agent's
 * thread at the answer (answered-link, architect m_24206); none for a
 * gate's approval.
 */
export type ApprovalFold = { ok: boolean, text: string, note?: string, card?: number | null, to?: string | null, };

/**
 * A `scheduled` entry (batch 3b): a task set or ended (the hub's
 * `scheduled` line) or a run (bise's wake), as the TUI's ◷ line says it:
 * `head` (`perf scheduled #48 · every 2m · 6 times · next 14:22`,
 * `scheduled #48 · 2 of 6 · check the build`, `scheduled #48 ended ·
 * stopped by you`), `words` the task's words under it ("" when ended).
 * Times are read at the line's own time, so a replay says the same.
 */
export type Scheduled = { id: number, head: string, words?: string, };

/**
 * A `turn_failed` entry (R12): why the turn failed, the runtime's words
 * (a provider's error, a missing key, a budget).
 */
export type TurnFailed = { why: string, };

/**
 * How a watch ended, as its thread says it (event-wake).
 */
export type WakeEv = "ended" | "still" | "stopped" | "expired" | "unknown";

/**
 * A `wake` entry (event-wake): what ended and how; [`words::wake_head`]
 * says it.
 */
export type WakeFold = { 
/**
 * the watch's id
 */
id: number, ev: WakeEv, kind: WatchKind, 
/**
 * its name (the agents row's `watching[].what`)
 */
what: string, 
/**
 * `what` is the agent's note (the row's `noted`)
 */
noted?: boolean, 
/**
 * its rc, when known (an ended bash command, a job, an rc file)
 */
rc?: number | null, 
/**
 * how long it waited
 */
after_ms: number, 
/**
 * the last lines of its output (at most 20, folded: `▸ its last 3
 * lines`); empty: none or no output file
 */
tail?: Array<string>, 
/**
 * the id of bise's message that woke the agent (folded into this
 * entry); none when nothing woke it
 */
msg?: number | null, 
/**
 * the agent the wake is for, when that is not this thread's own:
 * another agent's wake shown in main's thread (the hub writes the
 * same line there, core_wake.rs; the window folds it, tier 4). Empty:
 * this thread's own wake (and every line written before the field)
 */
agent?: string, };

/**
 * Where bise sent his words (a `you` entry's `went`): the project's hub
 * id and its name; with `agent`, an agent of this project instead (his
 * `@agent …` typed in this thread, at-start), `to` and `name` its name.
 */
export type Went = { to: string, name: string, agent?: boolean, };

/**
 * One entry of a thread.
 */
export type Entry = { 
/**
 * its first line's transcript position (`<agent>#<pos>`)
 */
pos: number, at_ms: number, kind: EntryKind, 
/**
 * markdown
 */
text: string, from?: string | null, tools?: Tools | null, card?: EntryCard | null, page?: PageRef | null, report?: ReportRef | null, 
/**
 * his message's fn context (S9): what was on his screen when he
 * spoke, from the `sb context : <json>` line right after his 'you'
 * line (the window draws the shot and the app on his message)
 */
context?: FnContext | null, 
/**
 * a `you` entry's mark (G1): where his message is, by the fold's one
 * rule ([`lines::deliver`], the TUI's too)
 */
delivery?: Delivery | null, 
/**
 * a `you` entry: his message's id (`m_12` is 12), from the
 * `sb you-id : m_12` line sb-core writes right after his 'you' line.
 * None for an older transcript (nothing guessed). A `from_agent`
 * entry's id is its `msg`, as before
 */
msg_id?: number | null, 
/**
 * the message reached the agent mid-turn (steered): the transcript
 * position of the `sb steered` receipt that names it, i.e. where in
 * the turn the agent read it (always after this entry's `pos`; one
 * receipt gives all its ids the same). None: not steered, or an
 * older transcript
 */
steered_at?: number | null, 
/**
 * an agent wrote this to him (G5, the TUI's level 2): an `agent`
 * entry from the hub's `msg-you` (`from`: who), or a `from_agent`
 * one that is an old direct reply. A superset: those lines fold to
 * the kinds they always did (architect m_14424)
 */
to_you?: boolean, 
/**
 * a `to_agent` entry: who it went to
 */
to?: string | null, 
/**
 * a `to_agent` entry: it waits for the reply (its question)
 */
asks?: boolean, 
/**
 * a `to_agent` entry: its message id (`m_12` is 12; the card main
 * opens for it says `for` the same)
 */
msg?: number | null, 
/**
 * a `thinking` entry's, or an `agent` reply's own: the reasoning
 * before it ("thought for 3.2s", folded)
 */
thinking?: Thinking | null, notice?: Notice | null, not_delivered?: NotDelivered | null, landed?: Landed | null, pr?: PrNews | null, made?: Made | null, answered?: Answered | null, approval?: ApprovalFold | null, scheduled?: Scheduled | null, turn_failed?: TurnFailed | null, wake?: WakeFold | null, 
/**
 * a `from_agent` entry an MCP App view wrote (sender `view`): its
 * plugin, so the thread says "via <plugin>" (docs/mcp-apps.md, C5)
 */
via_view?: string | null, 
/**
 * the first entry after a `turn_started` line: a turn starts here
 * (the TUI's turn row; a reply's turn ends before the next start)
 */
turn_start?: boolean, 
/**
 * the newest entry when its turn ended (any end: completed,
 * interrupted, failed), with the `turn_done` line's time (BISE-271:
 * the hover of the turn's replies); none for a replayed end (no
 * time) or one with no entry of its own to carry it
 */
turn_end_ms?: number | null, 
/**
 * his message as typed parts (msg-parts, [`crate::parts`]): on a
 * `you` entry, and on an `approval` entry that is his answer to a
 * card (the note's parts). From the `you-parts` / `route-parts` line
 * sb-core writes after it. When this is not empty, no client draws
 * his message from `text` (the model's templated text, kept for
 * older clients, search and copy)
 */
parts?: Array<Part>, 
/**
 * an `agent` entry cut off: the text he read as it streamed in,
 * kept when its turn failed before the answer came (the hub's `sb
 * kept` line); drawn dim, the failure's notice after it
 */
cut?: boolean, 
/**
 * a `you` entry: the view that brought his words (`bise`: bise's
 * home hub routed them here, his own words; the window and the TUI
 * say 'via bise'), from the `you` line's `via`
 */
via?: string | null, 
/**
 * a `you` entry in bise's main: his words went to a project, not
 * to main (the `routed` line with its id)
 */
went?: Went | null, };

/**
 * How a run of retries ended: the agent's text, its thinking or a tool
 * came in the same turn (recovered), or the turn failed.
 */
export type RetryEnd = "recovered" | "failed" | "unknown";

/**
 * A model call's retry (`provider_retry: 2/10 · <why> · retry in 4s`,
 * [`lines::retry`]): the attempt that failed, out of how many, why, the
 * wait before the next one, and how the run ended once it did.
 */
export type Retry = { attempt: number, max: number, why: string, wait_ms: number, 
/**
 * set by the fold when the run ends (the entry is sent again at its
 * pos): the window dims a recovered run, never guessing from the rows
 * after it
 */
end?: RetryEnd | null, };

/**
 * One entry's hits: its pos and how many matches it holds.
 */
export type FindHit = { pos: number, n: number, };

/**
 * One message of his: its entry's pos, when he sent it, his words cut short.
 */
export type Mark = { pos: number, at_ms: number, text: string, };
